const item = $input.first().json.body || $input.first().json;

const tournamentName = item.tournamentName || 'Society Premier League';
const sport = item.sport || 'CRICKET';
const format = item.format || 'KNOCKOUT';
const teams = item.teams || ['Titans', 'Strikers', 'Warriors', 'Knights'];
const venues = item.venues || ['Main Turf Ground', 'Clubhouse Court'];
const startDate = item.startDate || new Date().toISOString().split('T')[0];
const timeSlots = item.timeSlots || ['08:00 AM', '10:30 AM', '04:00 PM', '06:30 PM'];

const prompt = `You are the Lead Tournament Director for the Mana Community Sports Council.
Create an optimal, conflict-free match fixture schedule for this tournament.

Rules:
1. Ensure fair rest periods (no team should play consecutive matches on the same day if possible).
2. Maximize court/venue utilization across the specified time slots.
3. Include a Grand Finale as the culminating fixture.

Input Data:
- Tournament: ${tournamentName}
- Sport: ${sport}
- Format: ${format}
- Participating Teams (${teams.length}): ${teams.join(', ')}
- Venues: ${venues.join(', ')}
- Starting Date: ${startDate}
- Time Slots: ${timeSlots.join(', ')}

Respond ONLY with a valid JSON object matching this schema:
{
  "tournamentSummary": "Brief strategy on how fixtures were structured",
  "totalMatches": number,
  "fixtures": [
    {
      "matchNumber": number,
      "round": "Quarter Final" | "Semi Final" | "Final" | "League Group A",
      "teamA": string,
      "teamB": string,
      "venue": string,
      "date": "YYYY-MM-DD",
      "timeSlot": string,
      "notes": "Key matchup insight"
    }
  ],
  "fairnessAudit": "Brief explanation of rest interval balance"
}`;

return [{
  json: {
    tournamentName,
    sport,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedSchedule = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedSchedule = JSON.parse(rawText);
} catch (err) {
  parsedSchedule = {
    tournamentSummary: "Standard tournament bracket",
    totalMatches: 0,
    fixtures: [],
    fairnessAudit: "Balanced distribution"
  };
}

const meta = $('Format Schedule Prompt').first().json;

return [{
  json: {
    status: "success",
    tournamentName: meta.tournamentName,
    sport: meta.sport,
    generatedAt: new Date().toISOString(),
    schedule: parsedSchedule
  }
}];
